do $$ begin if not exists (select 1 from pg_enum where enumtypid = (select oid from pg_type where typname = 'app_permission' and nspname = 'rbac') and enumlabel = 'planetary.read') then alter type rbac.app_permission add value 'planetary.read'; alter type rbac.app_permission add value 'planetary.create'; alter type rbac.app_permission add value 'planetary.delete'; alter type rbac.app_permission add value 'astro.read'; alter type rbac.app_permission add value 'astro.create'; end if; end$$;
